import type { WixDataQueryOptions } from './types'

/**
 * Options builder for query operations.
 *
 * Use this builder to configure query behavior such as hooks suppression,
 * language, reference inclusion, and field groups.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataQueryOptionsBuilder {
  /**
   * Sets whether to suppress query hooks.
   *
   * When `true`, the query runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataQueryOptionsBuilder
  /**
   * Sets whether to include draft items in query results.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataQueryOptionsBuilder
  /**
   * Sets app-specific query options.
   */
  withAppOptions(value: Record<string, any>): WixDataQueryOptionsBuilder
  /**
   * Sets the language used for the query.
   */
  withLanguage(value: string): WixDataQueryOptionsBuilder
  /**
   * Sets whether the query uses consistent read mode.
   */
  withConsistentRead(value: boolean): WixDataQueryOptionsBuilder
  /**
   * Includes referenced items for the specified reference fields.
   *
   * Use `limit` to cap how many referenced items each field returns.
   */
  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataQueryOptionsBuilder
  /**
   * Sets whether to return the total result count with the query response.
   */
  withReturnTotalCount(value: boolean): WixDataQueryOptionsBuilder
  /**
   * Includes the specified field groups in the query results.
   */
  withIncludeFieldGroups(...value: string[]): WixDataQueryOptionsBuilder
  /**
   * Builds the query options object.
   */
  build(): WixDataQueryOptions
}

class WixDataQueryOptionsBuilderImpl implements WixDataQueryOptionsBuilder {
  constructor(private readonly options: WixDataQueryOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataQueryOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataQueryOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withAppOptions(value: Record<string, any>): WixDataQueryOptionsBuilder {
    return this.copy({ appOptions: { ...value } })
  }

  withLanguage(value: string): WixDataQueryOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(value: boolean): WixDataQueryOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataQueryOptionsBuilder {
    return this.copy({
      includeReferences: value.map((includeReference) => ({
        ...includeReference,
      })),
    })
  }

  withReturnTotalCount(value: boolean): WixDataQueryOptionsBuilder {
    return this.copy({ returnTotalCount: value })
  }

  withIncludeFieldGroups(...value: string[]): WixDataQueryOptionsBuilder {
    return this.copy({ includeFieldGroups: [...value] })
  }

  build(): WixDataQueryOptions {
    return {
      ...this.options,
      ...(this.options.appOptions
        ? { appOptions: { ...this.options.appOptions } }
        : {}),
      ...(this.options.includeReferences
        ? {
            includeReferences: this.options.includeReferences.map(
              (includeReference) => ({ ...includeReference })
            ),
          }
        : {}),
      ...(this.options.includeFieldGroups
        ? { includeFieldGroups: [...this.options.includeFieldGroups] }
        : {}),
    }
  }

  private copy(options: WixDataQueryOptions): WixDataQueryOptionsBuilder {
    return new WixDataQueryOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new query options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a query options builder"
 * import { items, QueryOptionsBuilder } from '@wix/data'
 *
 * const options = QueryOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withAppOptions({ key: 'value' })
 *   .withLanguage('en')
 *   .withConsistentRead(true)
 *   .withIncludeReferences([{ field: 'author', limit: 3 }])
 *   .withReturnTotalCount(true)
 *   .withIncludeFieldGroups('seo', 'details')
 *   .build()
 *
 * const result = await items.query<MyItem>(
 *   'myCollection',
 *   {},
 *   options
 * )
 * ```
 */
export const QueryOptionsBuilder: () => WixDataQueryOptionsBuilder = () =>
  new WixDataQueryOptionsBuilderImpl()
